SET foreign_key_checks = 0;

CREATE TABLE `os_account` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user` int(11) NOT NULL COMMENT 'User',
  `account_name` varchar(150) NOT NULL COMMENT 'Name',
  `account_type` int(11) NOT NULL COMMENT 'Type',
  `currency` int(11) NOT NULL COMMENT 'Currency',
  `institution` varchar(150) NOT NULL COMMENT 'Financial Institution',
  `credit_limit` decimal(12,2) DEFAULT 0.00 COMMENT 'Credit Limit',
  `default_account` tinyint(1) DEFAULT 0 COMMENT 'Default Account',
  `created` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT 'Created On',
  `modified` datetime DEFAULT NULL COMMENT 'Modified On',
  `status` enum('Active','Inactive') NOT NULL DEFAULT 'Active' COMMENT 'Status',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_account_type` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `title` varchar(50) NOT NULL COMMENT 'Type',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Status',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_acl` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `group_id` int(11) DEFAULT NULL,
  `controller` varchar(150) DEFAULT NULL,
  `actions` varchar(150) DEFAULT NULL,
  `action_title` varchar(150) DEFAULT NULL,
  `access` tinyint(1) DEFAULT 0,
  `controller_type` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=155 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_acl_action` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `controller_id` int(11) DEFAULT NULL,
  `title` varchar(150) DEFAULT NULL,
  `action` varchar(150) DEFAULT NULL,
  `controller_type` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=156 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_acl_controller` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `controller` varchar(150) DEFAULT NULL,
  `title` varchar(150) DEFAULT NULL,
  `controller_type` tinyint(2) DEFAULT NULL,
  `status` tinyint(1) DEFAULT 1,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_audit_trail` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user_id` int(11) NOT NULL COMMENT 'User',
  `login_time` timestamp NULL DEFAULT NULL COMMENT 'Login Time',
  `logout_time` timestamp NULL DEFAULT NULL COMMENT 'Logout Time',
  `user_type` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=77 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_backup` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `attachment` varchar(250) DEFAULT NULL COMMENT 'Attachment',
  `created_on` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT 'Created On',
  `created_by` int(11) DEFAULT NULL COMMENT 'Created By',
  PRIMARY KEY (`id`),
  KEY `created_by` (`created_by`),
  CONSTRAINT `os_backup_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `os_user_admin` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_banner` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `catid` int(10) unsigned NOT NULL DEFAULT 0,
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `alias` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '',
  `banner` varchar(255) DEFAULT '0',
  `clickurl` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT '',
  `description` text CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL,
  `published` tinyint(1) DEFAULT 1,
  `sticky` tinyint(1) DEFAULT 0,
  `ordering` int(11) DEFAULT 0,
  `created_on` datetime DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `publish_up` datetime DEFAULT '0000-00-00 00:00:00',
  `publish_down` datetime DEFAULT '0000-00-00 00:00:00',
  PRIMARY KEY (`id`),
  KEY `idx_banner_catid` (`catid`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_banner_category` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `parent_id` int(11) unsigned NOT NULL DEFAULT 0,
  `title` varchar(255) NOT NULL,
  `alias` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `description` mediumtext NOT NULL,
  `published` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_time` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `modified_by` int(11) DEFAULT NULL,
  `modified_time` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  PRIMARY KEY (`id`),
  KEY `cat_idx` (`published`),
  KEY `idx_alias` (`alias`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;




CREATE TABLE `os_city` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `country_id` int(11) DEFAULT NULL,
  `state_id` int(11) DEFAULT NULL,
  `city_name` varchar(255) DEFAULT NULL,
  `city_3_code` varchar(9) DEFAULT NULL,
  `city_2_code` varchar(6) DEFAULT NULL,
  `ordering` double DEFAULT NULL,
  `published` tinyint(1) DEFAULT NULL,
  `created_on` datetime DEFAULT NULL,
  `created_by` double DEFAULT NULL,
  `modified_on` datetime DEFAULT NULL,
  `modified_by` double DEFAULT NULL,
  `locked_on` datetime DEFAULT NULL,
  `locked_by` double DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=78 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_content` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL DEFAULT '',
  `alias` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL DEFAULT '',
  `introtext` text NOT NULL,
  `fulltext` text NOT NULL,
  `state` tinyint(3) NOT NULL DEFAULT 1,
  `catid` int(10) unsigned NOT NULL DEFAULT 0,
  `created` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `created_by` int(10) unsigned NOT NULL DEFAULT 0,
  `modified` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `modified_by` int(10) unsigned NOT NULL DEFAULT 0,
  `publish_up` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `publish_down` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `ordering` int(11) NOT NULL DEFAULT 0,
  `metakey` text NOT NULL,
  `metadesc` text NOT NULL,
  `hits` int(10) unsigned NOT NULL DEFAULT 0,
  `featured` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `images` varchar(250) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_state` (`state`),
  KEY `idx_catid` (`catid`),
  KEY `idx_createdby` (`created_by`),
  KEY `idx_featured_catid` (`featured`,`catid`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

