CREATE TABLE `os_transaction` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user` int(11) NOT NULL COMMENT 'User',
  `description` varchar(250) NOT NULL COMMENT 'Description',
  `amount` decimal(13,2) NOT NULL COMMENT 'Amount',
  `created` date DEFAULT NULL COMMENT 'Date',
  `modified` datetime DEFAULT '0000-00-00 00:00:00' COMMENT 'Modified On',
  `transaction_type` int(11) DEFAULT NULL COMMENT 'Type',
  `account` varchar(50) NOT NULL COMMENT 'Account',
  `tag` varchar(250) DEFAULT NULL COMMENT 'Tags',
  `group` int(11) DEFAULT NULL COMMENT 'Group',
  `status` tinyint(3) DEFAULT 1 COMMENT 'Status',
  `notes` varchar(250) DEFAULT NULL COMMENT 'Notes',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=28637 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_transaction_budget` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user` int(11) NOT NULL COMMENT 'User',
  `tag_name` int(11) NOT NULL COMMENT 'Tag',
  `amount` decimal(13,2) NOT NULL DEFAULT 0.00 COMMENT 'Amount',
  `created` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00' COMMENT 'Created On',
  `modified` datetime DEFAULT '0000-00-00 00:00:00' COMMENT 'Modofied On',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_transaction_contact` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user` int(11) NOT NULL COMMENT 'User',
  `contact_name` varchar(150) NOT NULL COMMENT 'Name',
  `email` varchar(150) DEFAULT NULL COMMENT 'Email',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_transaction_group` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user` int(11) NOT NULL COMMENT 'User',
  `title` varchar(150) NOT NULL COMMENT 'Group name',
  `members` varchar(250) DEFAULT NULL COMMENT 'Members',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_transaction_status` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `title` varchar(50) NOT NULL COMMENT 'Title',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Status',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_transaction_tag` (
  `transaction` int(11) NOT NULL COMMENT 'Transaction',
  `tag` int(11) NOT NULL COMMENT 'Tag',
  UNIQUE KEY `transaction` (`transaction`,`tag`),
  KEY `tag` (`tag`),
  CONSTRAINT `os_transaction_tag_ibfk_1` FOREIGN KEY (`transaction`) REFERENCES `os_transaction` (`id`),
  CONSTRAINT `os_transaction_tag_ibfk_2` FOREIGN KEY (`tag`) REFERENCES `os_tag` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_transaction_type` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `title` varchar(50) NOT NULL COMMENT 'Type',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Status',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_user` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(255) NOT NULL COMMENT 'Name',
  `username` varchar(150) NOT NULL COMMENT 'Username',
  `email` varchar(100) NOT NULL COMMENT 'Email',
  `password` varchar(100) NOT NULL COMMENT 'Password',
  `registerDate` datetime NOT NULL DEFAULT '0000-00-00 00:00:00' COMMENT 'Register Date',
  `lastvisitDate` datetime NOT NULL DEFAULT '0000-00-00 00:00:00' COMMENT 'Last Visit',
  `activation` varchar(100) NOT NULL DEFAULT '' COMMENT 'Activation',
  `group_id` int(11) DEFAULT 0 COMMENT 'Group',
  `status` tinyint(1) DEFAULT NULL COMMENT 'Status',
  `user_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'User Type',
  PRIMARY KEY (`id`),
  KEY `idx_name` (`name`),
  KEY `username` (`username`),
  KEY `email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=1106 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;




CREATE TABLE `os_user_admin` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `username` varchar(150) NOT NULL,
  `email` varchar(100) NOT NULL,
  `password` varchar(100) NOT NULL,
  `registerDate` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `lastvisitDate` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `profile_picture` varchar(250) DEFAULT NULL,
  `activation` varchar(100) NOT NULL DEFAULT '',
  `group_id` int(11) DEFAULT 0,
  `status` tinyint(1) DEFAULT NULL,
  `user_type` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `idx_name` (`name`),
  KEY `username` (`username`),
  KEY `email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;




CREATE TABLE `os_user_group` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT 'Primary Key',
  `title` varchar(100) NOT NULL,
  `details` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_usergroup_parent_title_lookup` (`title`),
  KEY `idx_usergroup_title_lookup` (`title`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;




CREATE TABLE `os_user_profile` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user_id` int(11) NOT NULL COMMENT 'User',
  `country_id` int(11) DEFAULT NULL COMMENT 'Country',
  `profile_picture` varchar(255) DEFAULT NULL COMMENT 'Profile Picture',
  `state_id` int(11) DEFAULT NULL COMMENT 'State/Division',
  `city_id` int(11) DEFAULT NULL COMMENT 'City',
  `address` varchar(255) DEFAULT NULL COMMENT 'Address',
  `mobile` varchar(100) DEFAULT NULL COMMENT 'Mobile',
  `phone` varchar(100) DEFAULT NULL COMMENT 'Phone',
  `fax` varchar(100) DEFAULT NULL COMMENT 'Fax',
  `website` varchar(150) DEFAULT NULL COMMENT 'Website',
  `birth_date` date DEFAULT '0000-00-00' COMMENT 'Birth Date',
  `gender` tinyint(1) DEFAULT NULL COMMENT 'Gender',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_user_id_profile_key` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=106 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='Simple user profile storage table';




CREATE TABLE `os_user_setting` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `user` int(11) DEFAULT NULL COMMENT 'User',
  `currency` int(11) DEFAULT NULL COMMENT 'Currency',
  `Currency_format` int(11) DEFAULT NULL COMMENT 'Display format',
  `Timezone` int(11) DEFAULT NULL COMMENT 'Timezone',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_user_status` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `status` varchar(255) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;




CREATE TABLE `os_visitor` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_type` tinyint(1) DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  `user_name` varchar(100) DEFAULT NULL,
  `page_title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL,
  `page_link` varchar(150) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL,
  `server_time` timestamp NULL DEFAULT NULL,
  `browser` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL,
  `visitor_ip` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7274 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;




CREATE TABLE `os_weblink` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` int(11) NOT NULL,
  `title` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `click_url` varchar(250) NOT NULL,
  `created_on` datetime DEFAULT '0000-00-00 00:00:00',
  `created_by` int(11) DEFAULT NULL,
  `hits` int(11) DEFAULT NULL,
  `published` tinyint(1) DEFAULT 1,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `os_weblink_category` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `parent_id` int(11) unsigned NOT NULL DEFAULT 0,
  `title` varchar(255) NOT NULL,
  `alias` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `description` mediumtext NOT NULL,
  `published` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_time` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `modified_by` int(11) DEFAULT NULL,
  `modified_time` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  PRIMARY KEY (`id`),
  KEY `cat_idx` (`published`),
  KEY `idx_alias` (`alias`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;




CREATE TABLE `os_yiisession` (
  `id` char(32) NOT NULL,
  `expire` int(11) DEFAULT NULL,
  `data` longblob DEFAULT NULL,
  `userId` int(11) DEFAULT NULL,
  `userType` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;


SET foreign_key_checks = 1;